// Values from the Google Sheet take priority; empty fields fall back to the default settings
const defaults = $('Set Default Conference Settings').first().json;
const first = $input.first();
const row = (first && first.json && !first.json.error) ? first.json : {};

function isEmpty(v) { return v === undefined || v === null || String(v).trim() === ''; }

// Time zone: sheet value if valid, otherwise default setting, otherwise Europe/Berlin
const source = {};
let tz = defaults.timezone || 'Europe/Berlin';
source.timezone = 'default';
if (!isEmpty(row.timezone) && DateTime.local().setZone(String(row.timezone).trim()).isValid) {
  tz = String(row.timezone).trim();
  source.timezone = 'google_sheet';
}

function toIso(v) {
  if (isEmpty(v)) return null;
  if (typeof v === 'number') {
    // Google Sheets serial number (days since 1899-12-30)
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: tz }).plus({ milliseconds: Math.round(v * 86400000) }).toFormat("yyyy-MM-dd'T'HH:mm:ss");
  }
  const s = String(v).trim();
  let dt = DateTime.fromISO(s, { zone: tz });
  const formats = ['dd.MM.yyyy HH:mm:ss', 'dd.MM.yyyy HH:mm', 'd.M.yyyy HH:mm', 'd.M.yyyy H:mm', 'yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd HH:mm', 'dd.MM.yyyy'];
  for (const f of formats) {
    if (dt.isValid) break;
    dt = DateTime.fromFormat(s, f, { zone: tz });
  }
  return dt.isValid ? dt.toFormat("yyyy-MM-dd'T'HH:mm:ss") : null;
}

function value(field, convert) {
  const raw = row[field];
  const v = convert ? convert(raw) : (isEmpty(raw) ? null : raw);
  if (v === null || v === undefined || (typeof v === 'number' && isNaN(v))) {
    source[field] = 'default';
    return defaults[field];
  }
  source[field] = 'google_sheet';
  return v;
}

const result = {
  matching_deadline: value('matching_deadline', toIso),
  matching_criteria: value('matching_criteria'),
  meeting_start: value('meeting_start', toIso),
  meeting_duration_minutes: Number(value('meeting_duration_minutes', function (v) { return isEmpty(v) ? null : Number(String(v).replace(',', '.')); })),
  meeting_title: value('meeting_title'),
  timezone: tz,
};
result.settings_source = source;
return [{ json: result }];

const seen = new Set();
const participants = [];
for (const item of $input.all()) {
  const email = String(item.json.email || "").trim().toLowerCase();
  if (!email || seen.has(email)) continue;
  seen.add(email);
  participants.push({ name: item.json.name || "", email: email, description: item.json.description || "" });
}
if (participants.length < 2) return [];
const list = participants.map(function (p) { return "- " + p.name + " <" + p.email + ">: " + (p.description || "(no description)"); }).join("\n");
return [{ json: { participants: participants, participant_list: list, count: participants.length } }];

const participants = $('Organize Participants').first().json.participants;
const byEmail = {};
for (const p of participants) byEmail[p.email] = p;
const groups = ($input.first().json.output || {}).groups || [];
const used = new Set();
const result = [];
for (const g of groups) {
  const members = (g.emails || []).map(function (e) { return String(e).trim().toLowerCase(); }).filter(function (e, i, arr) { return byEmail[e] && !used.has(e) && arr.indexOf(e) === i; });
  if (members.length < 2) continue;
  members.forEach(function (e) { used.add(e); });
  result.push({ emails: members, reason: g.reason || "" });
}
// Pair up anyone left unassigned; a single remaining person joins the last group (group of 3)
const rest = participants.map(function (p) { return p.email; }).filter(function (e) { return !used.has(e); });
while (rest.length >= 2) result.push({ emails: rest.splice(0, 2), reason: "Random match" });
if (rest.length === 1) {
  if (result.length > 0) result[result.length - 1].emails.push(rest[0]);
}
return result.map(function (g) {
  const people = g.emails.map(function (e) { return byEmail[e]; });
  return { json: {
    attendee_emails: g.emails.join(","),
    names: people.map(function (p) { return p.name; }).join(" & "),
    reason: g.reason,
    members: people.map(function (p) {
      return { email: p.email, partner_emails: g.emails.filter(function (e) { return e !== p.email; }).join(",") };
    })
  } };
});
